{
  "part": {
    "name": "Combination wrench with recessed handle",
    "description": "A single-piece, constant-thickness combination wrench comprising an open-ended jaw, a straight load-carrying handle with a shallow upper-face recess, and a circular box-end eye. The STEP model has one solid, one shell, 26 faces, nominal 15 mm thickness, a 20 mm box-end bore, and an approximately 20 mm open-jaw interface.",
    "source_views": [
      "front",
      "back",
      "left",
      "right",
      "top",
      "bottom",
      "toprightiso"
    ],
    "symmetry_note": "The plan profile is approximately bilaterally symmetric about the longitudinal x=0 center plane, although the STEP coordinates show small left-right deviations in the outer jaw and transition curves. The 15 mm-thick base body is symmetric through its thickness before addition of the 1 mm-deep recess on the y=15 upper side; that recess breaks thickness-direction symmetry."
  },
  "Section": [
    {
      "id": "S01",
      "name": "Open-ended jaw",
      "features included": [
        "Two fixed wrench prongs",
        "Approximately 20 mm wide open fastener slot",
        "Parallel internal jaw flats",
        "Rounded internal throat",
        "Large convex outer head arcs",
        "Blended transitions into the handle"
      ],
      "function intent": "Engages two opposing flats of an accessible nut or bolt head and transfers applied handle torque into the fastener.",
      "physical behavior": "The parallel inner flats apply opposing contact forces to the fastener. The thick prongs resist bending and spreading, while the rounded throat and broad outer curves reduce stress concentration and route reaction loads into the handle.",
      "geometry": "A 15 mm-thick open head at the negative-z end. Two prongs are separated by parallel inner faces at x approximately -10 mm and +10 mm. The slot terminates in a flat throat joined to the inner flats by 5 mm-radius cylindrical corners. Large convex cylindrical outer surfaces form the widened jaw envelope.",
      "location": "At the negative-z end of the part, opposite the circular box eye.",
      "colour": {
        "R": 220,
        "G": 72,
        "B": 65
      },
      "major_faces": [
        {
          "face_code": "0000",
          "name": "Right outer jaw arc",
          "Brep_id": "FACE 16",
          "description": "Large convex cylindrical side surface forming the outside of the right-hand jaw prong."
        },
        {
          "face_code": "0001",
          "name": "Right inner jaw flat",
          "Brep_id": "FACE 22",
          "description": "Planar fastener-contact surface on the right prong, extending from the open tip toward the throat."
        },
        {
          "face_code": "0002",
          "name": "Right throat blend",
          "Brep_id": "FACE 17",
          "description": "Concave 5 mm-radius cylindrical corner connecting the right jaw flat to the throat end."
        },
        {
          "face_code": "0003",
          "name": "Throat end flat",
          "Brep_id": "FACE 18",
          "description": "Planar transverse surface closing the inner end of the open-jaw slot."
        },
        {
          "face_code": "0004",
          "name": "Left throat blend",
          "Brep_id": "FACE 19",
          "description": "Concave 5 mm-radius cylindrical corner connecting the throat end to the left jaw flat."
        },
        {
          "face_code": "0005",
          "name": "Left inner jaw flat",
          "Brep_id": "FACE 20",
          "description": "Planar fastener-contact surface on the left prong, extending from the throat toward the open tip."
        },
        {
          "face_code": "0006",
          "name": "Left outer jaw arc",
          "Brep_id": "FACE 23",
          "description": "Large convex cylindrical side surface forming the outside of the left-hand jaw prong."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "S01",
          "target id": "S02",
          "function relationship": "transmits_load, distributes_stress",
          "structural relationship": "attached_to, blends_into"
        },
        {
          "source id": "S01",
          "target id": "S03",
          "function relationship": "transmits_load",
          "structural relationship": "offset_from"
        }
      ]
    },
    {
      "id": "S02",
      "name": "Central handle and common body lands",
      "features included": [
        "Straight rectangular shank",
        "Continuous upper body land",
        "Continuous lower body face",
        "Left and right longitudinal sidewalls",
        "Four rounded head-to-handle transition bands",
        "Primary torque-transmitting spine"
      ],
      "function intent": "Provides hand leverage and structurally connects the open jaw to the box-end eye while maintaining adequate bending and torsional stiffness.",
      "physical behavior": "The long, approximately 20 mm wide by 15 mm thick shank acts as a beam and torsion member. Its broad upper and lower lands carry longitudinal tension and compression, while the sidewalls carry shear. Rounded transitions spread stress where the narrow handle enters the wider heads.",
      "geometry": "A substantially straight shank extending between z approximately -110 mm and -2 mm, bounded by long planar sidewalls near x=-10 mm and x=+10 mm. Cylindrical transition patches of approximately 5 mm radius blend both sides into the end heads. STEP FACE 24 and FACE 25 are continuous planar B-rep faces spanning the handle and exposed lands of both heads.",
      "location": "Longitudinal center of the part between the open-ended jaw and circular box eye.",
      "colour": {
        "R": 65,
        "G": 133,
        "B": 225
      },
      "major_faces": [
        {
          "face_code": "0007",
          "name": "Right jaw-side transition",
          "Brep_id": "FACE 15",
          "description": "Convex cylindrical blend carrying the right handle edge into the wider open-jaw head."
        },
        {
          "face_code": "0008",
          "name": "Right handle sidewall",
          "Brep_id": "FACE 14",
          "description": "Long planar side surface on the positive-x edge of the handle."
        },
        {
          "face_code": "0009",
          "name": "Right eye-side transition",
          "Brep_id": "FACE 13",
          "description": "Convex cylindrical blend connecting the right handle sidewall to the box-end outer rim."
        },
        {
          "face_code": "0010",
          "name": "Upper body land",
          "Brep_id": "FACE 24",
          "description": "Continuous y=15 planar upper face surrounding the handle recess and extending across both wrench heads."
        },
        {
          "face_code": "0011",
          "name": "Left eye-side transition",
          "Brep_id": "FACE 11",
          "description": "Convex cylindrical blend connecting the box-end outer rim to the left handle sidewall."
        },
        {
          "face_code": "0012",
          "name": "Left handle sidewall",
          "Brep_id": "FACE 10",
          "description": "Long planar side surface on the negative-x edge of the handle."
        },
        {
          "face_code": "0013",
          "name": "Left jaw-side transition",
          "Brep_id": "FACE 9",
          "description": "Convex cylindrical blend carrying the left handle edge into the wider open-jaw head."
        },
        {
          "face_code": "0014",
          "name": "Lower body face",
          "Brep_id": "FACE 25",
          "description": "Continuous y=0 planar underside spanning the handle and both end heads."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "S02",
          "target id": "S01",
          "function relationship": "transmits_load, supports",
          "structural relationship": "attached_to, blends_into"
        },
        {
          "source id": "S02",
          "target id": "S03",
          "function relationship": "transmits_load, distributes_stress",
          "structural relationship": "attached_to, blends_into"
        },
        {
          "source id": "S02",
          "target id": "S04",
          "function relationship": "provides_clearance, supports",
          "structural relationship": "contains, adjacent_to"
        }
      ]
    },
    {
      "id": "S03",
      "name": "Box-end eye",
      "features included": [
        "Circular through-bore",
        "Annular torque-transfer rim",
        "Convex outer circumference",
        "Closed fastener interface",
        "Blended neck connection to handle"
      ],
      "function intent": "Encloses a compatible fastener head or mating pin to provide a closed, positively located torque interface with reduced slip risk.",
      "physical behavior": "The cylindrical bore locates the mating feature radially and constrains lateral translation. Contact load is distributed around the bore circumference into the annular rim, which then transfers torque through the curved neck transitions into the handle.",
      "geometry": "An annular 15 mm-thick head at the positive-z end. The through-bore is a 10 mm-radius cylinder centered near x=0, z=10 mm. The external rim is principally a cylinder of approximately 14.92 mm radius and merges into the handle through two rounded side transitions.",
      "location": "At the positive-z end of the part, opposite the open-ended jaw.",
      "colour": {
        "R": 70,
        "G": 180,
        "B": 105
      },
      "major_faces": [
        {
          "face_code": "0015",
          "name": "Outer eye circumference",
          "Brep_id": "FACE 12",
          "description": "Convex cylindrical surface forming the exposed outer perimeter of the circular box-end rim."
        },
        {
          "face_code": "0016",
          "name": "Eye bore",
          "Brep_id": "FACE 21",
          "description": "Full cylindrical through-hole of 10 mm radius providing the closed mating and torque interface."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "S03",
          "target id": "S02",
          "function relationship": "transmits_load, locates_mating_part, constrains_dof",
          "structural relationship": "attached_to, blends_into"
        },
        {
          "source id": "S03",
          "target id": "S01",
          "function relationship": "transmits_load",
          "structural relationship": "offset_from"
        }
      ]
    },
    {
      "id": "S04",
      "name": "Upper handle recess",
      "features included": [
        "Shallow rectangular cavity",
        "Large planar recessed floor",
        "Two long sidewalls",
        "Two transverse end walls",
        "Four 1 mm-radius vertical corner blends"
      ],
      "function intent": "Reduces local material and mass, creates a visually defined handle panel, and can provide a shallow grip, label, or identification area without substantially weakening the main shank.",
      "physical behavior": "The approximately 1 mm-deep pocket removes low-stress surface material while retaining a perimeter frame and most of the 15 mm body thickness. Rounded corners reduce notch sensitivity and improve manufacturability compared with sharp internal corners.",
      "geometry": "A shallow rounded-rectangle pocket in the y=15 upper side of the handle. Its planar floor lies at y=14 mm, is approximately 14.44 mm wide and 91.25 mm long, and is bounded by 1 mm-high planar walls with 1 mm-radius corner cylinders.",
      "location": "Centered on the upper face of the central handle, terminating before both widened end heads.",
      "colour": {
        "R": 238,
        "G": 179,
        "B": 58
      },
      "major_faces": [
        {
          "face_code": "0017",
          "name": "Recess floor",
          "Brep_id": "FACE 1",
          "description": "Large planar pocket bottom at y=14 mm, one millimeter below the upper body land."
        },
        {
          "face_code": "0018",
          "name": "Eye-side recess end wall",
          "Brep_id": "FACE 2",
          "description": "Short transverse planar wall closing the recess at its positive-z end."
        },
        {
          "face_code": "0019",
          "name": "Right recess sidewall",
          "Brep_id": "FACE 4",
          "description": "Long planar vertical wall along the positive-x side of the shallow pocket."
        },
        {
          "face_code": "0020",
          "name": "Jaw-side recess end wall",
          "Brep_id": "FACE 8",
          "description": "Short transverse planar wall closing the recess at its negative-z end."
        },
        {
          "face_code": "0021",
          "name": "Left recess sidewall",
          "Brep_id": "FACE 7",
          "description": "Long planar vertical wall along the negative-x side of the shallow pocket."
        }
      ],
      "minor_faces_Brep_id": [
        "FACE 0",
        "FACE 3",
        "FACE 5",
        "FACE 6"
      ],
      "relationships": [
        {
          "source id": "S04",
          "target id": "S02",
          "function relationship": "provides_clearance, distributes_stress",
          "structural relationship": "contained_in, shares_face"
        }
      ]
    }
  ]
}
